      backup_text =
        "type Student = (\n\
        \  name= String,\n\
        \  age= Int,\n\
        \  favorite_color= String\n\
         ) in\n\
         let students : [Student] = (\n\
        \  [\n\
        \    (\"Bob\", 12, \"blue\"),\n\
        \    (\"Alice\", 17, \"green\"),\n\
        \    (\"Eve\", 13, \"red\")\n\
        \  ]\n\
         ) in\n\
         type GradebookEntry = (\n\
        \  name= String,\n\
        \  age= Int,\n\
        \  quiz1= Int,\n\
        \  quiz2= Int,\n\
        \  midterm= Int,\n\
        \  quiz3= Int,\n\
        \  quiz4= Int,\n\
        \  final= Int\n\
         ) in\n\
         let gradebook : [GradebookEntry] = (\n\
        \  [\n\
        \    (\"Bob\",   12, 8, 9, 77, 7, 9, 87),\n\
        \    (\"Alice\", 17, 6, 8, 88, 8, 7, 85),\n\
        \    (\"Eve\", 13, 7, 9, 84, 8, 8, 77)\n\
        \  ]\n\
         ) in\n\n\
         # V1 (idiomatic): This version is idiomatic but is a higher order \
         function requiring the caller to construct the resulting schema by \
         passing in a function. #\n\
         # In addition the right side of the table is wrapped in a single \
         option type marking the whole row as present or absent. A future \
         operation could turn a optional tuple into a tuple of optional values \
         #\n\
         let v1 =\n\
        \  let requires = [\n\
        \    (enforced=(\"static\"), \"cs has no duplicates\"), # Ensured by \
         projection function #\n\
        \    (enforced=(\"static\"), \"for all c in cs, c is in header(t1)\"), \
         # Ensured by projection function #\n\
        \    (enforced=(\"static\"), \"for all c in cs, c is in header(t2)\"), \
         # Ensured by projection function #\n\
        \    (enforced=(\"static\"), \"for all c in cs, schema(t1)[c] is equal \
         to schema(t2)[c]\"), # Ensured by projection function #\n\
        \    (\n\
        \      enforced=(\"no\"),\n\
        \      \"concat(header(t1), removeAll(header(t2), cs)) has no \
         duplicates\"\n\
        \    )\n\
        \  ] in\n\
        \  let ensures = [\n\
        \    (enforced=(\"no\"), \"header(t3) is equal to concat(header(t1), \
         removeAll(header(t2), cs))\"),\n\
        \    (enforced=(\"static\"), \"for all c in header(t1), schema(t3)[c] \
         is equal to schema(t1)[c]\"), # If combine function is just adding \
         new column#\n\
        \    (enforced=(\"no\"), \"for all c in removeAll(header(t2), cs), \
         schema(t3)[c] is equal to schema(t2)[c]\"),\n\
        \    (\n\
        \      enforced=(\"no\"),\n\
        \      \"nrows(t3) is equal to nrows(t1) if distinct(selectColumns(t2, \
         cs)) is equal to selectColumns(t2, cs), otherwise each row of t1 may \
         have several matches\"\n\
        \    )\n\
        \  ] in\n\
        \  # We just require the caller to combine the resulting rows. The \
         closest to leftJoin would be to just wrap the right row in a new \
         column. #\n\
        \  # The caller could also decide to flatten the option type into \
         individual optional columns #\n\
        \  let left_join =\n\
        \    typfun r1 ->\n\
        \      typfun r2 ->\n\
        \        typfun r3 ->\n\
        \          typfun k ->\n\
        \            fun (\n\
        \              t1 : [r1],\n\
        \              t2 : [r2],\n\
        \              proj1 : r1 -> k,\n\
        \              proj2 : r2 -> k,\n\
        \              combine : (r1, (+ None + Some(r2))) -> r3\n\
        \            ) ->\n\
        \              flat_map(\n\
        \                t1,\n\
        \                fun (r1 : r1) ->\n\
        \                  let t2' =\n\
        \                    filter(t2, fun (r2 : r2) -> proj1(r1) == \
         proj2(r2)) in\n\
        \                  case t2'\n\
        \                  | [] => [combine(r1, None)]\n\
        \                  | _ => map(t2', fun (r2 : r2) -> combine(r1, \
         Some(r2)))\n\
        \                  end\n\
        \              )\n\
        \              : [r3] in\n\
        \  # Examples #\n\
        \  test\n\
        \    left_join@<Student>@<GradebookEntry>@<(\n\
        \      name= String,\n\
        \      age= Int,\n\
        \      favorite_color= String,\n\
        \      gradebook= (+ None + Some(GradebookEntry))\n\
        \    )>@<String>(\n\
        \      students,\n\
        \      gradebook,\n\
        \      fun (s : Student) -> s.name,\n\
        \      fun (g : GradebookEntry) -> g.name,\n\
        \      fun (s, g) -> s ... (gradebook= g)\n\
        \    )\n\
        \    == (\n\
        \      [\n\
        \        (\"Bob\", 12, \"blue\", Some(\"Bob\", 12, 8, 9, 77, 7, 9, 87)),\n\
        \        (\"Alice\", 17, \"green\", Some(\"Alice\", 17, 6, 8, 88, 8, \
         7, 85)),\n\
        \        (\"Eve\", 13, \"red\", Some(\"Eve\", 13, 7, 9, 84, 8, 8, 77))\n\
        \      ]\n\
        \      : (\n\
        \        [\n\
        \          (\n\
        \            name= String,\n\
        \            age= Int,\n\
        \            favorite_color= String,\n\
        \            gradebook= (+ None + Some(GradebookEntry))\n\
        \          )\n\
        \        ]\n\
        \      )\n\
        \    ) end in\n\n\
         # V2 (benchmark): This version works by dynamically building the \
         schema from the first row of each table. It closely matches the Table \
         API but does not gurantee many constraints. #\n\
         let v2 =\n\
        \  let requires = [\n\
        \    (enforced=(\"no\"), \"cs has no duplicates\"),\n\
        \    (enforced=(\"no\"), \"for all c in cs, c is in header(t1)\"),\n\
        \    (enforced=(\"no\"), \"for all c in cs, c is in header(t2)\"),\n\
        \    (enforced=(\"no\"), \"for all c in cs, schema(t1)[c] is equal to \
         schema(t2)[c]\"),\n\
        \    (\n\
        \      enforced=(\"no\"),\n\
        \      \"concat(header(t1), removeAll(header(t2), cs)) has no \
         duplicates\"\n\
        \    )\n\
        \  ] in\n\
        \  let ensures = [\n\
        \    (enforced=(\"live\"), \"header(t3) is equal to concat(header(t1), \
         removeAll(header(t2), cs))\"),\n\
        \    (enforced=(\"live\"), \"for all c in header(t1), schema(t3)[c] is \
         equal to schema(t1)[c]\"),\n\
        \    (enforced=(\"live\"), \"for all c in removeAll(header(t2), cs), \
         schema(t3)[c] is equal to schema(t2)[c]\"),\n\
        \    (\n\
        \      enforced=(\"no\"),\n\
        \      \"nrows(t3) is equal to nrows(t1) if distinct(selectColumns(t2, \
         cs)) is equal to selectColumns(t2, cs), otherwise each row of t1 may \
         have several matches\"\n\
        \    )\n\
        \  ] in\n\
        \  # Since we don't have the schema as a runtime value there's no way \
         to dynamically build up the right table columns unless there's at \
         least one row. So we extract the columns from the first row. #\n\
        \  # If there is no row we just return the lefthand table's columns #\n\
        \  # All the columns of the right table are wrapped in an option type \
         since they may be absent#\n\
        \  let left_join =\n\
        \    let project_labels_str =\n\
        \      fun (v, cs) ->\n\
        \        to_lvs(v)\n\
        \        |> filter(_, fun e -> mem(cs, e.label))\n\
        \        |> from_lvs in\n\
        \    let omit_labels_str =\n\
        \      fun (v, cs) ->\n\
        \        to_lvs(v)\n\
        \        |> filter(_, fun e -> ! mem(cs, e.label))\n\
        \        |> from_lvs in\n\
        \    let make_optional =\n\
        \      fun (v) ->\n\
        \        to_lvs(v)\n\
        \        |> map(_, fun e -> e ... (value= Some(e.value)))\n\
        \        |> from_lvs in\n\
        \    fun (t1 : [?], t2 : [?], cs : [String]) ->\n\
        \      let right_columns =\n\
        \        case hd_opt(t2)\n\
        \        |None => []\n\
        \        |Some(v) => to_lvs(v) |> map(_, fun e -> e.label)\n\
        \        end in\n\
        \      flat_map(\n\
        \        t1,\n\
        \        fun r1 ->\n\
        \          let matched =\n\
        \            filter(\n\
        \              t2,\n\
        \              fun r2 ->\n\
        \                project_labels_str(r2, cs) == project_labels_str(r1, \
         cs)\n\
        \            ) in\n\
        \          case matched\n\
        \          | [] =>\n\
        \            [\n\
        \              r1\n\
        \              ... (\n\
        \                from_lvs(\n\
        \                  map(\n\
        \                    filter(right_columns, fun e -> !mem(cs, e)),\n\
        \                    fun lc -> (label= lc, value= None)\n\
        \                  )\n\
        \                )\n\
        \              )\n\
        \            ]\n\
        \          | _ =>\n\
        \            map(\n\
        \              matched,\n\
        \              fun r2 -> r1 ... (make_optional(omit_labels_str(r2, cs)))\n\
        \            )\n\
        \          end\n\
        \      ) in\n\
        \  # Examples #\n\
        \  test\n\
        \    left_join(students, gradebook, [\"name\", \"age\"])\n\
        \    == (\n\
        \      [\n\
        \        (\"Bob\", 12, \"blue\", Some(8), Some(9), Some(77), Some(7), \
         Some(9), Some(87)),\n\
        \        (\"Alice\", 17, \"green\", Some(6), Some(8), Some(88), \
         Some(8), Some(7), Some(85)),\n\
        \        (\"Eve\", 13, \"red\", Some(7), Some(9), Some(84), Some(8), \
         Some(8), Some(77))\n\
        \      ]\n\
        \      : (\n\
        \        [\n\
        \          (\n\
        \            name= String,\n\
        \            age= Int,\n\
        \            favorite_color= String,\n\
        \            quiz1= Option,\n\
        \            quiz2= Option,\n\
        \            midterm= Option,\n\
        \            quiz3= Option,\n\
        \            quiz4= Option,\n\
        \            final= Option\n\
        \          )\n\
        \        ]\n\
        \      )\n\
        \    ) end in\n\
         ?\n";
      refractors = "()";
    } )
